/**
 * Verify that the public wrapper of the internal substitution logic
 * expands expressions in exactly the same way.
 */
@Test
public void testCommonVariableSubstitution() {
  conf.set("intvar", "42");
  conf.set("my.int", "${intvar}");

  // null in, null out
  assertNull(conf.substituteCommonVariables(null));
  // an expression without any variable is returned untouched
  assertEquals("literal", conf.substituteCommonVariables("literal"));
  // single and chained references are expanded
  assertEquals("42", conf.substituteCommonVariables("${intvar}"));
  assertEquals("42", conf.substituteCommonVariables("${my.int}"));
  assertEquals("value is 42",
      conf.substituteCommonVariables("value is ${my.int}"));
  // undefined variables are returned as-is
  assertEquals("a${my.undefvar}b",
      conf.substituteCommonVariables("a${my.undefvar}b"));
  // the same value is returned as by the standard getter
  assertEquals(conf.get("my.int"),
      conf.substituteCommonVariables(conf.getRaw("my.int")));

  // failures are propagated: a cycle spanning multiple keys requires
  // more replacements than the maximum substitution depth allows
  conf.set("ping", "${pong}");
  conf.set("pong", "${ping}");
  try {
    conf.substituteCommonVariables("${ping}");
    fail("Expected an exception for an over-deep substitution");
  } catch (IllegalStateException expected) {
    GenericTestUtils.assertExceptionContains(
        "Variable substitution depth too large", expected);
  }
}
